34	    getRecordFields: {
35	      description: 'Returns all stored fields for one entry, or null when absent.',
36	      input: entryIdInputSchema,
37	      output: recordFieldsOutputSchema,
38	      handler: (input, ctx) => ctx.self.state[input.entryId] ?? null,
